package com.mohymods.kingdomsmp.economy;
import static org.junit.jupiter.api.Assertions.*;
import com.mohymods.kingdomsmp.profession.*;
import com.mohymods.kingdomsmp.persistence.AtomicNbt;
import java.util.*;
import java.nio.file.*;
import java.io.IOException;
import net.minecraft.nbt.CompoundTag;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
class SmithProgressStoreTest {
 @TempDir Path directory;UUID p=UUID.randomUUID();
 EconomyStore enrolled()throws Exception{var s=EconomyStore.open(directory);s.changeProfession(UUID.randomUUID(),p,"enroll","","blacksmith");return s;}
 void firstFive(EconomyStore s)throws Exception{for(String id:List.of(CraftDeliveryQuests.FUEL,CraftDeliveryQuests.IRON,CraftDeliveryQuests.RODS,CraftDeliveryQuests.TOOLS,CraftDeliveryQuests.SHIELDS)){var inputs=id.equals(CraftDeliveryQuests.FUEL)?Map.of("minecraft:coal",64):CraftDeliveryQuests.defaults(id);var pending=s.prepareProfessionDelivery(UUID.randomUUID(),p,id,"Pure canonical model adapter fixture",inputs);s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence()));}}
 void contract(EconomyStore s,long day,int tier)throws Exception{var item=new CompoundTag();item.putString("id","minecraft:iron_ingot");item.putInt("count",1);var delivery=tier==0?s.prepareContract(UUID.randomUUID(),p,"blacksmith","daily",day,16,160,2000,item):s.prepareContract(UUID.randomUUID(),p,"blacksmith","daily",day,16,160,2000,item,tier);s.recoverItem(new EconomyStore.Receipt(s.id(),delivery.sequence()));}
 @Test void exactThreeTierPinnedPeriodsAwardOnceAndCannotReuseUnknownOrEarlyHistory()throws Exception{var s=enrolled();contract(s,10,0);contract(s,11,2);assertEquals(0,s.commissionContractPeriods(p,"kingdom_smp:blacksmith/a07"));contract(s,12,3);contract(s,13,3);assertThrows(IllegalStateException.class,()->s.completeCommissionQuest(UUID.randomUUID(),p,"kingdom_smp:blacksmith/a07",3));contract(s,14,3);s.completeCommissionQuest(UUID.randomUUID(),p,"kingdom_smp:blacksmith/a07",3);assertEquals(100,s.professions(p).track(Profession.BLACKSMITH).xp());assertEquals(5,s.mailbox(p).size());assertEquals(0,s.balance(p));assertThrows(IllegalStateException.class,()->s.completeCommissionQuest(UUID.randomUUID(),p,"kingdom_smp:blacksmith/a07",3));s.archive(p,"Native smith commission model audit");assertEquals(3,EconomyStore.open(directory).commissionContractPeriods(p,"kingdom_smp:blacksmith/a07"));}
 @Test void repairCannotUseInspectionAuthorityOrSkipToolsAndAfterRenameNeverDuplicatesXp()throws Exception{var s=enrolled();assertThrows(IllegalStateException.class,()->s.completeRepairQuest(UUID.randomUUID(),p,4,4));assertThrows(IllegalArgumentException.class,()->s.approveProfessionInspection(UUID.randomUUID(),UUID.randomUUID(),p,RepairService.QUEST,"Wrong repair authority"));firstFive(s);assertThrows(IllegalArgumentException.class,()->s.completeRepairQuest(UUID.randomUUID(),p,4,3));var operation=UUID.randomUUID();var bad=EconomyStore.open(directory,(file,data)->{AtomicNbt.write(file,data);throw new IOException("Native repair after rename");});assertThrows(IOException.class,()->bad.completeRepairQuest(operation,p,4,4));var restored=EconomyStore.open(directory);restored.completeRepairQuest(operation,p,4,4);assertEquals(600,restored.professions(p).track(Profession.BLACKSMITH).xp());assertThrows(IllegalStateException.class,()->restored.completeRepairQuest(UUID.randomUUID(),p,4,4));assertTrue(restored.mailbox(p).isEmpty());assertEquals(0,restored.balance(p));}
 @Test void journeymanDeliveryNeedsEarnedEarlierBandAndRecoversExactNewMaterialGroupsOnce()throws Exception{
  var s=enrolled();firstFive(s);assertThrows(IllegalStateException.class,()->s.prepareProfessionDelivery(UUID.randomUUID(),p,CraftDeliveryQuests.GOLD,"Early gold must refuse",CraftDeliveryQuests.defaults(CraftDeliveryQuests.GOLD)));s.completeRepairQuest(UUID.randomUUID(),p,4,4);for(long day=20;day<23;day++)contract(s,day,3);s.completeCommissionQuest(UUID.randomUUID(),p,"kingdom_smp:blacksmith/a07",3);s.approveProfessionInspection(UUID.randomUUID(),UUID.randomUUID(),p,"kingdom_smp:blacksmith/a08","Pure canonical model complete forge");
  s.prepareProfessionDelivery(UUID.randomUUID(),p,CraftDeliveryQuests.GOLD,"Exact reviewed gold and clocks",CraftDeliveryQuests.defaults(CraftDeliveryQuests.GOLD));assertFalse(s.recoverItem(new EconomyStore.Receipt(s.id(),s.expectedReceipt(p))));assertEquals(800,s.professions(p).track(Profession.BLACKSMITH).xp());
  var pending=s.prepareProfessionDelivery(UUID.randomUUID(),p,CraftDeliveryQuests.GOLD,"Exact reviewed gold and clocks",CraftDeliveryQuests.defaults(CraftDeliveryQuests.GOLD));var receipt=new EconomyStore.Receipt(s.id(),pending.sequence());var faulty=EconomyStore.open(directory,(file,data)->{AtomicNbt.write(file,data);throw new IOException("Journeyman output receipt after rename");});assertThrows(IOException.class,()->faulty.recoverItem(receipt));var restored=EconomyStore.open(directory);assertFalse(restored.recoverItem(receipt));assertEquals(1000,restored.professions(p).track(Profession.BLACKSMITH).xp());assertThrows(IllegalStateException.class,()->restored.prepareProfessionDelivery(UUID.randomUUID(),p,CraftDeliveryQuests.GOLD,"Duplicate gold",CraftDeliveryQuests.defaults(CraftDeliveryQuests.GOLD)));assertThrows(IllegalArgumentException.class,()->restored.prepareProfessionDelivery(UUID.randomUUID(),p,CraftDeliveryQuests.ARMOUR,"Incomplete armour set",Map.of("minecraft:iron_chestplate",4)));
  for(String id:List.of(CraftDeliveryQuests.DIAMOND,CraftDeliveryQuests.ARMOUR)){var next=restored.prepareProfessionDelivery(UUID.randomUUID(),p,id,"Exact native output model boundary",CraftDeliveryQuests.defaults(id));assertTrue(restored.recoverItem(new EconomyStore.Receipt(restored.id(),next.sequence())));}restored.archive(p,"Journeyman native delivery receipt audit");assertEquals(1400,EconomyStore.open(directory).professions(p).track(Profession.BLACKSMITH).xp());assertEquals(0,restored.balance(p));assertEquals(3,restored.mailbox(p).size());
 }
 @Test void smithWeeklyJourneymanNeedsTwoDistinctEligiblePeriodsAndPreservesFundedMailOnRecovery()throws Exception{
  var s=enrolled();firstFive(s);s.completeRepairQuest(UUID.randomUUID(),p,4,4);for(long day=30;day<33;day++)contract(s,day,3);s.completeCommissionQuest(UUID.randomUUID(),p,"kingdom_smp:blacksmith/a07",3);s.approveProfessionInspection(UUID.randomUUID(),UUID.randomUUID(),p,"kingdom_smp:blacksmith/a08","Pure model earned Apprentice forge");var iron=new CompoundTag();iron.putString("id","minecraft:iron_ingot");iron.putInt("count",1);
  var old=s.prepareContract(UUID.randomUUID(),p,"blacksmith","weekly",100,128,1280,10000,iron,3);s.recoverItem(new EconomyStore.Receipt(s.id(),old.sequence()));assertEquals(0,s.commissionContractPeriods(p,"kingdom_smp:blacksmith/j07"));
  for(long week=101;week<103;week++){var q=s.prepareContract(UUID.randomUUID(),p,"blacksmith","weekly",week,128,1280,10000,iron,4);s.recoverItem(new EconomyStore.Receipt(s.id(),q.sequence()));if(week==101)assertThrows(IllegalStateException.class,()->s.completeCommissionQuest(UUID.randomUUID(),p,"kingdom_smp:blacksmith/j07",2));}
  var operation=UUID.randomUUID();var failed=EconomyStore.open(directory,(file,data)->{AtomicNbt.write(file,data);throw new IOException("Smith weekly XP after rename");});assertThrows(IOException.class,()->failed.completeCommissionQuest(operation,p,"kingdom_smp:blacksmith/j07",2));var restored=EconomyStore.open(directory);restored.completeCommissionQuest(operation,p,"kingdom_smp:blacksmith/j07",2);assertEquals(1000,restored.professions(p).track(Profession.BLACKSMITH).xp());assertEquals(6,restored.mailbox(p).size());assertEquals(1280,restored.contractPoolSpent("weekly",102));assertEquals(0,restored.balance(p));
 }
 @Test void sameKindTrimDeliveryRecoversOnceAndMixedKindsCannotEnterTheJournal()throws Exception{
  var s=enrolled();firstFive(s);s.completeRepairQuest(UUID.randomUUID(),p,4,4);for(long day=40;day<43;day++)contract(s,day,3);s.completeCommissionQuest(UUID.randomUUID(),p,"kingdom_smp:blacksmith/a07",3);s.approveProfessionInspection(UUID.randomUUID(),UUID.randomUUID(),p,"kingdom_smp:blacksmith/a08","Pure model earned forge prerequisites");long revision=s.revision();assertThrows(IllegalArgumentException.class,()->s.prepareProfessionDelivery(UUID.randomUUID(),p,TrimCopies.QUEST,"Mixed kinds must refuse",Map.of("minecraft:coast_armor_trim_smithing_template",1,"minecraft:dune_armor_trim_smithing_template",1)));assertEquals(revision,s.revision());assertTrue(s.pendingItem().isEmpty());
  var input=Map.of("minecraft:coast_armor_trim_smithing_template",2);var pending=s.prepareProfessionDelivery(UUID.randomUUID(),p,TrimCopies.QUEST,"Actual native copy recipe boundary",input);var receipt=new EconomyStore.Receipt(s.id(),pending.sequence());var fault=EconomyStore.open(directory,(file,data)->{AtomicNbt.write(file,data);throw new IOException("Trim after rename");});assertThrows(IOException.class,()->fault.recoverItem(receipt));var restored=EconomyStore.open(directory);assertFalse(restored.recoverItem(receipt));assertEquals(1000,restored.professions(p).track(Profession.BLACKSMITH).xp());assertThrows(IllegalStateException.class,()->restored.prepareProfessionDelivery(UUID.randomUUID(),p,TrimCopies.QUEST,"Duplicate copies",input));assertEquals(0,restored.balance(p));assertEquals(3,restored.mailbox(p).size());
 }
}
